class Solution {
  private static int vowels(String w) {
    int c = 0;
    for (int i = 0; i < w.length(); i++) if ("aeiou".indexOf(w.charAt(i)) >= 0) c++;
    return c;
  }

  public String reverseWords(String s) {
    String[] words = s.split(" ");
    int target = vowels(words[0]);
    StringBuilder sb = new StringBuilder(words[0]);
    for (int i = 1; i < words.length; i++) {
      sb.append(' ');
      if (vowels(words[i]) == target) sb.append(new StringBuilder(words[i]).reverse());
      else sb.append(words[i]);
    }
    return sb.toString();
  }
}
